from typing import List

def component_root(primes: List[int], eps: float, i: int) -> int:
    """Single-linkage component root of index i at scale eps.

    Returns the least index k <= i such that every gap on [k, i) is <= eps, i.e.
    the leftmost point connected to p_i by a chain of edges of length <= eps.
    Equivalently, scan left from i and stop at the first gap exceeding eps.
    Two indices share an eps-component iff they have the same root, so counting
    distinct roots over {0,...,n} yields the Betti number b0(eps, n).
    """
    k = i
    while k > 0 and primes[k] - primes[k - 1] <= eps:
        k -= 1
    return k

def betti_via_roots(primes: List[int], eps: float, n: int) -> int:
    roots = {component_root(primes, eps, i) for i in range(n + 1)}
    return len(roots)
